"use client";

import {
  type CSSProperties,
  createContext,
  type FieldsetHTMLAttributes,
  type InputHTMLAttributes,
  type LabelHTMLAttributes,
  type ReactNode,
  use,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import { type RadioOrientation, radioTokens } from "../tokens/components/radio";
import { cn } from "../utils/cn";

type RadioValue = string;

type RadioGroupContextValue = {
  readonly name: string;
  readonly value: RadioValue;
  readonly disabled: boolean;
  readonly required: boolean;
  readonly setValue: (value: RadioValue) => void;
};

const RadioGroupContext = createContext<RadioGroupContextValue | null>(null);

type RadioGroupStyle = CSSProperties & {
  "--radio-group-gap": string;
  "--radio-label-gap": string;
  "--radio-label-size": string;
  "--radio-label-weight": number;
};

type RadioItemStyle = CSSProperties & {
  "--radio-item-gap": string;
  "--radio-item-min-height": string;
  "--radio-item-size": string;
  "--radio-item-weight": number;
  "--radio-description-size": string;
  "--radio-description-gap": string;
  "--radio-control-size": string;
  "--radio-dot-size": string;
  "--radio-border-width": string;
  "--radio-motion-duration": string;
  "--radio-motion-easing": string;
};

type RadioGroupBaseProps = Omit<
  FieldsetHTMLAttributes<HTMLFieldSetElement>,
  "children" | "defaultValue" | "disabled" | "onChange" | "value"
>;

export type RadioGroupProps = RadioGroupBaseProps & {
  children: ReactNode;
  /** Visible group label rendered as a native legend. */
  label?: ReactNode;
  /** Form field name shared by all radios. Generated when omitted. */
  name?: string;
  /** Controlled selected value. */
  value?: RadioValue;
  /** Uncontrolled initial selected value. */
  defaultValue?: RadioValue;
  /** Geist-compatible change callback. */
  onChange?: (value: RadioValue) => void;
  /** Base UI / Radix-compatible change callback. */
  onValueChange?: (value: RadioValue) => void;
  disabled?: boolean;
  required?: boolean;
  orientation?: RadioOrientation;
  /** Applies to the options container. */
  className?: string;
  /** Applies to the fieldset root. */
  rootClassName?: string;
};

export type RadioProps = Omit<
  InputHTMLAttributes<HTMLInputElement>,
  "children" | "className" | "type"
> &
  (
    | { "aria-label": string; "aria-labelledby"?: string | undefined; id?: string | undefined }
    | { "aria-labelledby": string; "aria-label"?: string | undefined; id?: string | undefined }
    | { id: string; "aria-label"?: string | undefined; "aria-labelledby"?: string | undefined }
  ) & {
    className?: string | undefined;
    indicatorClassName?: string | undefined;
    inputClassName?: string | undefined;
  };

export type RadioGroupItemProps = Omit<
  LabelHTMLAttributes<HTMLLabelElement>,
  "children" | "onChange"
> & {
  value: RadioValue;
  defaultChecked?: boolean;
  children?: ReactNode;
  description?: ReactNode;
  disabled?: boolean;
  disabledReason?: string;
  controlClassName?: string;
  inputClassName?: string;
};

export type UseRadioProps = {
  value: RadioValue;
  disabled?: boolean;
  disabledReason?: string;
  id?: string;
  "aria-label"?: string;
  "aria-labelledby"?: string;
};

const itemStyle: RadioItemStyle = {
  "--radio-item-gap": `${radioTokens.item.gap}px`,
  "--radio-item-min-height": `${radioTokens.item.minHeight}px`,
  "--radio-item-size": `${radioTokens.item.fontSize}px`,
  "--radio-item-weight": radioTokens.item.fontWeight,
  "--radio-description-size": `${radioTokens.item.descriptionSize}px`,
  "--radio-description-gap": `${radioTokens.item.descriptionGap}px`,
  "--radio-control-size": `${radioTokens.control.size}px`,
  "--radio-dot-size": `${radioTokens.control.dotSize}px`,
  "--radio-border-width": `${radioTokens.control.borderWidth}px`,
  "--radio-motion-duration": `${radioTokens.motion.duration}ms`,
  "--radio-motion-easing": radioTokens.motion.easing,
};

const radioControlClassName = cn(
  "relative inline-flex shrink-0 items-center justify-center rounded-[var(--radius-full)] border-[length:var(--radio-border-width)] border-border bg-background text-foreground",
  "size-[var(--radio-control-size)]",
  "transition-[background-color,border-color,box-shadow] duration-[var(--radio-motion-duration)] ease-[var(--radio-motion-easing)]",
  "after:size-[var(--radio-dot-size)] after:scale-0 after:rounded-[var(--radius-full)] after:bg-current after:opacity-0 after:transition-[opacity,transform] after:duration-[var(--radio-motion-duration)] after:ease-[var(--radio-motion-easing)] after:content-['']",
  "peer-checked:border-[var(--neutral-12)] peer-checked:after:scale-100 peer-checked:after:opacity-100",
  "peer-focus-visible:outline-none peer-focus-visible:ring-2 peer-focus-visible:ring-ring peer-focus-visible:ring-offset-2",
  "peer-disabled:border-[var(--neutral-5)] peer-disabled:bg-muted peer-disabled:text-[var(--neutral-8)]",
);

function useRadioGroupContext() {
  return use(RadioGroupContext);
}

function RadioRoot({ className, indicatorClassName, inputClassName, ...props }: RadioProps) {
  return (
    <span className={cn("inline-flex items-center", className)}>
      <input type="radio" className={cn("peer sr-only", inputClassName)} {...props} />
      <span aria-hidden="true" className={cn(radioControlClassName, indicatorClassName)} />
    </span>
  );
}

RadioRoot.displayName = "Radio";

function RadioGroupItemRoot({
  children,
  className,
  controlClassName,
  description,
  disabled,
  disabledReason,
  id,
  inputClassName,
  style,
  value,
  ...props
}: RadioGroupItemProps) {
  const generatedId = useId();
  const inputId = id ?? `radio-${generatedId.replace(/:/g, "")}`;
  const reasonId = disabledReason ? `${inputId}-reason` : undefined;
  const descriptionId = description ? `${inputId}-description` : undefined;
  const context = useRadioGroupContext();
  const isDisabled = Boolean(disabled || context?.disabled);
  const isChecked = context ? context.value === value : undefined;
  const required = context?.required;
  const name = context?.name;
  const describedBy = [descriptionId, reasonId].filter(Boolean).join(" ");

  const radio = (
    <RadioRoot
      id={inputId}
      value={value}
      disabled={isDisabled}
      indicatorClassName={controlClassName}
      inputClassName={inputClassName}
      onChange={(event) => {
        if (event.currentTarget.checked) {
          context?.setValue(value);
        }
      }}
      {...(name ? { name } : {})}
      {...(isChecked === undefined ? {} : { checked: isChecked })}
      {...(context || props.defaultChecked === undefined
        ? {}
        : { defaultChecked: props.defaultChecked })}
      {...(required ? { required } : {})}
      {...(describedBy ? { "aria-describedby": describedBy } : {})}
      {...(!children && props["aria-label"] ? { "aria-label": props["aria-label"] } : {})}
      {...(props["aria-labelledby"] ? { "aria-labelledby": props["aria-labelledby"] } : {})}
    />
  );

  const mergedStyle = { ...itemStyle, ...style };

  if (!children && !description) {
    return (
      <span
        className={cn(
          "inline-flex min-h-[var(--radio-item-min-height)] items-center gap-[var(--radio-item-gap)]",
          isDisabled && "cursor-not-allowed opacity-60",
          className,
        )}
        style={mergedStyle}
        title={isDisabled ? disabledReason : undefined}
      >
        {radio}
        {disabledReason ? (
          <span id={reasonId} className="sr-only">
            {disabledReason}
          </span>
        ) : null}
      </span>
    );
  }

  return (
    <label
      htmlFor={inputId}
      className={cn(
        "group inline-flex min-h-[var(--radio-item-min-height)] items-start gap-[var(--radio-item-gap)] text-[length:var(--radio-item-size)] text-foreground leading-5",
        isDisabled ? "cursor-not-allowed opacity-60" : "cursor-pointer",
        className,
      )}
      style={mergedStyle}
      title={isDisabled ? disabledReason : undefined}
      {...props}
    >
      <span className="pt-0.5">{radio}</span>
      <span className="min-w-0">
        <span style={{ fontWeight: "var(--radio-item-weight)" }}>{children}</span>
        {description ? (
          <span
            id={descriptionId}
            className="mt-[var(--radio-description-gap)] block text-[length:var(--radio-description-size)] text-muted-foreground leading-4"
          >
            {description}
          </span>
        ) : null}
        {disabledReason ? (
          <span id={reasonId} className="sr-only">
            {disabledReason}
          </span>
        ) : null}
      </span>
    </label>
  );
}

RadioGroupItemRoot.displayName = "RadioGroupItem";

function RadioGroupRoot({
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  children,
  className,
  defaultValue = "",
  disabled = false,
  label,
  name,
  onChange,
  onValueChange,
  orientation = "vertical",
  required = false,
  rootClassName,
  style,
  value,
  ...props
}: RadioGroupProps) {
  const generatedName = useId();
  const initialDefaultValue = useRef(defaultValue);
  const [internalValue, setInternalValue] = useState(initialDefaultValue.current);
  const isControlled = value !== undefined;
  const selectedValue = isControlled ? value : internalValue;
  const legendId = useId();

  const groupStyle: RadioGroupStyle = {
    "--radio-group-gap": `${radioTokens.group.gap}px`,
    "--radio-label-gap": `${radioTokens.group.labelGap}px`,
    "--radio-label-size": `${radioTokens.label.fontSize}px`,
    "--radio-label-weight": radioTokens.label.fontWeight,
    ...style,
  };

  const contextValue = useMemo<RadioGroupContextValue>(
    () => ({
      name: name ?? `radio-group-${generatedName.replace(/:/g, "")}`,
      value: selectedValue,
      disabled,
      required,
      setValue: (nextValue) => {
        if (!isControlled) {
          setInternalValue(nextValue);
        }
        onChange?.(nextValue);
        onValueChange?.(nextValue);
      },
    }),
    [disabled, generatedName, isControlled, name, onChange, onValueChange, required, selectedValue],
  );

  return (
    <fieldset
      disabled={disabled}
      aria-label={label ? undefined : ariaLabel}
      aria-labelledby={label ? legendId : ariaLabelledBy}
      className={cn("m-0 min-w-0 border-0 p-0", rootClassName)}
      style={groupStyle}
      {...props}
    >
      {label ? (
        <legend
          id={legendId}
          className="mb-[var(--radio-label-gap)] text-[length:var(--radio-label-size)] text-foreground"
          style={{ fontWeight: "var(--radio-label-weight)" }}
        >
          {label}
        </legend>
      ) : null}
      <RadioGroupContext.Provider value={contextValue}>
        <div
          className={cn(
            "flex gap-[var(--radio-group-gap)]",
            orientation === "vertical" ? "flex-col" : "flex-row flex-wrap",
            className,
          )}
          data-orientation={orientation}
        >
          {children}
        </div>
      </RadioGroupContext.Provider>
    </fieldset>
  );
}

RadioGroupRoot.displayName = "RadioGroup";

export function useRadio({
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  disabled,
  disabledReason,
  id,
  value,
}: UseRadioProps) {
  const context = useRadioGroupContext();
  const generatedId = useId();
  const inputId = id ?? `radio-${generatedId.replace(/:/g, "")}`;
  const reasonId = disabledReason ? `${inputId}-reason` : undefined;
  const isDisabled = Boolean(disabled || context?.disabled);
  const checked = context ? context.value === value : false;

  const inputProps = {
    id: inputId,
    value,
    checked,
    disabled: isDisabled,
    onChange: () => context?.setValue(value),
    ...(context?.name ? { name: context.name } : {}),
    ...(context?.required ? { required: context.required } : {}),
    ...(reasonId ? { "aria-describedby": reasonId } : {}),
    ...(ariaLabel ? { "aria-label": ariaLabel } : {}),
    ...(ariaLabelledBy ? { "aria-labelledby": ariaLabelledBy } : {}),
  } satisfies RadioProps;

  return {
    checked,
    disabled: isDisabled,
    inputProps,
    component: (
      <>
        <RadioRoot {...inputProps} id={inputId} />
        {disabledReason ? (
          <span id={reasonId} className="sr-only">
            {disabledReason}
          </span>
        ) : null}
      </>
    ),
  };
}

export const Radio = RadioRoot;
export const RadioGroupItem = RadioGroupItemRoot;
export const RadioGroup = Object.assign(RadioGroupRoot, {
  Item: RadioGroupItemRoot,
});

/**
 * Primitive Design Tokens — Layer 1
 *
 * Raw values only. No CSS variable references, no semantic meaning.
 * These are the "atoms" of the design system.
 *
 * Color source: @nebutra/brand `colors` → @nebutra/design-tokens `tokens/core.json` (SSOT).
 * Typography:   Geist + Geist Mono (Vercel) with Noto Sans SC + PingFang SC + Microsoft YaHei CJK fallbacks.
 *               Aligned with @nebutra/design-tokens SSOT.
 */

import { colors } from "@nebutra/brand";

// ─── Color Palette ────────────────────────────────────────────────────────────

export const primitiveColors = {
  // Nebutra Blue (云毓蓝) — technology & trust — VI: #0033FE
  blue50: colors.primary[50],
  blue100: colors.primary[100],
  blue200: colors.primary[200],
  blue300: colors.primary[300],
  blue400: colors.primary[400],
  blue500: colors.primary[500], // brand primary
  blue600: colors.primary[600],
  blue700: colors.primary[700],
  blue800: colors.primary[800],
  blue900: colors.primary[900],
  blue950: colors.primary[950],

  // Nebutra Cyan (云毓青) — data flow & intelligence — VI: #0BF1C3
  cyan50: colors.accent[50],
  cyan100: colors.accent[100],
  cyan200: colors.accent[200],
  cyan300: colors.accent[300],
  cyan400: colors.accent[400],
  cyan500: colors.accent[500], // brand secondary
  cyan600: colors.accent[600],
  cyan700: colors.accent[700],
  cyan800: colors.accent[800],
  cyan900: colors.accent[900],
  cyan950: colors.accent[950],

  // Neutral (blue-undertone gray scale)
  neutral50: colors.neutral[50],
  neutral100: colors.neutral[100],
  neutral200: colors.neutral[200],
  neutral300: colors.neutral[300],
  neutral400: colors.neutral[400],
  neutral500: colors.neutral[500],
  neutral600: colors.neutral[600],
  neutral700: colors.neutral[700],
  neutral800: colors.neutral[800],
  neutral900: colors.neutral[900],
  neutral950: colors.neutral[950], // deepest — used as dark background

  // Semantic raw colors — VI §Color Specifications
  // NOTE: info = brand blue (#0033FE), not sky/teal
  red500: "#ef4444",
  red600: "#dc2626",
  green500: "#22c55e", // VI manual specifies this exact value for success
  green600: "#16a34a",
  amber500: "#f59e0b",
  amber600: "#d97706",

  white: colors.white,
  black: colors.black,
} as const;

export type PrimitiveColor = keyof typeof primitiveColors;

// ─── Brand Gradients — VI §Brand Gradients (first-class design assets) ────────

export const primitiveGradients = {
  /** Hero sections, primary CTA buttons, logo fills — VI signature gradient */
  primary: colors.gradient.primary,
  /** Hover states, secondary gradient elements */
  reverse: colors.gradient.primaryReverse,
  /** Vertical layout dividers, page section separators */
  vertical: colors.gradient.primaryVertical,
  /** Background halos, focus glow effects, radial emphasis */
  radial: colors.gradient.primaryRadial,
  /** Dark mode card surfaces — deep brand-blue tinted */
  darkCard: "linear-gradient(135deg, #020617 0%, #0a1628 100%)",
} as const;

export type PrimitiveGradient = keyof typeof primitiveGradients;

// ─── Spacing Scale (px values) ────────────────────────────────────────────────

export const primitiveSpacing = {
  0: 0,
  1: 4,
  2: 8,
  3: 12,
  4: 16,
  5: 20,
  6: 24,
  8: 32,
  10: 40,
  12: 48,
  14: 56,
  16: 64,
  20: 80,
  24: 96,
} as const;

export type PrimitiveSpacing = keyof typeof primitiveSpacing;

// ─── Layout Containers (px) — max-width standards ────────────────────────────
// Use `text` for text-heavy sections (hero copy, CTA), `content` for general
// sections, and `wide` for full-bleed feature bento grids.

export const primitiveContainer = {
  /** Text-focused: hero headlines, CTA copy, FAQ — optimized for reading */
  text: 896, // ~56rem / max-w-4xl
  /** Standard content sections: pricing, architecture, blog */
  content: 1152, // ~72rem / max-w-6xl
  /** Wide sections: feature bento, testimonials, product demos */
  wide: 1400, // ~87.5rem — Vercel/Supabase standard
} as const;

export type PrimitiveContainer = keyof typeof primitiveContainer;

// ─── Sizing Scale — component heights (px) ────────────────────────────────────

export const primitiveSizing = {
  xs: 20,
  /** Geist button-specific size (24px). Larger than xs by design. */
  tiny: 24,
  sm: 32,
  md: 40,
  lg: 48,
  xl: 56,
  "2xl": 80,
} as const;

export type PrimitiveSizing = keyof typeof primitiveSizing;

// ─── Border Radius (px) ───────────────────────────────────────────────────────

export const primitiveRadius = {
  none: 0,
  sm: 4,
  md: 6, // Geist default — slightly more rounded than 4px
  lg: 8,
  xl: 12,
  "2xl": 16,
  full: 9999,
} as const;

export type PrimitiveRadius = keyof typeof primitiveRadius;

// ─── Font Sizes (px) ──────────────────────────────────────────────────────────

export const primitiveFontSize = {
  xs: 12,
  sm: 14,
  base: 16,
  lg: 18,
  xl: 20,
  "2xl": 24,
  "3xl": 30,
  "4xl": 36,
} as const;

export type PrimitiveFontSize = keyof typeof primitiveFontSize;

// ─── Font Weights ─────────────────────────────────────────────────────────────

export const primitiveFontWeight = {
  light: 300,
  normal: 400,
  medium: 500,
  semibold: 600,
  bold: 700,
} as const;

export type PrimitiveFontWeight = keyof typeof primitiveFontWeight;

// ─── Font Families — VI §Typography ──────────────────────────────────────────
// Aligned with @nebutra/design-tokens SSOT (tokens/core.json fontFamily.*).
// EN primary: Geist (Vercel variable, 100–900)
// EN mono:    Geist Mono
// CN primary: Noto Sans SC → PingFang SC → Microsoft YaHei → vivo Sans (print)

export const primitiveFontFamily = {
  /** Default body/UI stack — Geist with CJK auto-fallbacks */
  sans: '"Geist", "Noto Sans SC", "PingFang SC", "Microsoft YaHei", -apple-system, BlinkMacSystemFont, system-ui, sans-serif',
  /** Chinese body/UI stack */
  cnSans: '"Noto Sans SC", "PingFang SC", "Microsoft YaHei", "vivo Sans", sans-serif',
  /** Display / hero headlines */
  display: '"Geist", "Noto Sans SC", sans-serif',
  /** Heading (alias of display) */
  heading: '"Geist", "Noto Sans SC", sans-serif',
  /** Code / monospace — Geist Mono pairs with Geist for full family coverage */
  mono: '"Geist Mono", ui-monospace, SFMono-Regular, "SF Mono", Menlo, monospace',
} as const;

export type PrimitiveFontFamily = keyof typeof primitiveFontFamily;

// ─── Shadows ──────────────────────────────────────────────────────────────────

export const primitiveShadow = {
  none: "none",
  sm: "0 1px 2px 0 rgb(0 0 0 / 0.05)",
  md: "0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1)",
  lg: "0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1)",
  xl: "0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1)",
  /** Brand glow — blue tone for focus/highlight states */
  brandGlow: "0 0 0 3px rgb(0 51 254 / 0.15)",
} as const;

export type PrimitiveShadow = keyof typeof primitiveShadow;

// ─── Transition ───────────────────────────────────────────────────────────────

/**
 * Primitive transition tokens — aligned with the four-rail motion scale
 * (SSOT: @nebutra/design-tokens core.json → duration.*).
 * Keys mirror semantic.json motion.duration.*; values are in ms.
 */
export const primitiveTransition = {
  duration: {
    micro: 100, // hover, focus, small state changes
    flow: 200, // standard state transitions (default)
    reveal: 300, // larger motion (accordion, modal, drawer)
    cinematic: 500, // hero entrance, big delight moments
  },
  easing: {
    default: "ease-out",
    spring: "cubic-bezier(0.34, 1.56, 0.64, 1)",
    inOut: "cubic-bezier(0.4, 0, 0.2, 1)",
  },
} as const;

// ─── Focus Ring ───────────────────────────────────────────────────────────────

export const primitiveFocusRing = {
  width: 2, // px
  offset: 2, // px — gap between element and ring
} as const;

import {
  primitiveFontSize,
  primitiveFontWeight,
  primitiveRadius,
  primitiveSizing,
  primitiveSpacing,
  primitiveTransition,
} from "../primitive";

export const radioOrientations = ["vertical", "horizontal"] as const;
export type RadioOrientation = (typeof radioOrientations)[number];

export const radioTokens = {
  group: {
    gap: primitiveSpacing[3],
    labelGap: primitiveSpacing[2],
  },
  item: {
    gap: primitiveSpacing[2],
    minHeight: primitiveSizing.xs,
    fontSize: primitiveFontSize.sm,
    fontWeight: primitiveFontWeight.normal,
    descriptionSize: primitiveFontSize.xs,
    descriptionGap: primitiveSpacing[1],
  },
  control: {
    size: 16,
    dotSize: 6,
    borderWidth: 1,
    radius: primitiveRadius.full,
  },
  label: {
    fontSize: primitiveFontSize.sm,
    fontWeight: primitiveFontWeight.medium,
  },
  motion: {
    duration: primitiveTransition.duration.micro,
    easing: primitiveTransition.easing.default,
  },
} as const;
